"""Russian calendar entries. TEXT = {English name: {type, life, patron}}.

The calendar's life is the opening of the Saints index life, so a saint's two
lives are written together and neither has to be come back to.

Only the fields that have been written are given; anything absent falls back
to the English, which is how the hundred and forty-six entries already in
index.html behave. The type field is left alone for the fore-, after- and
leavetaking feasts: the English calls them "Saint", which is a slip in the
categorising rather than something to carry into Russian, and inventing a
better word for them here would be this file correcting the data instead of
translating it.
"""
